  "cta.all": {
   "t": "Semua versi di GitHub",
   "en": "All versions on GitHub"
  },
  "cta.note": {
   "t": "Butuh Android 16 ke atas. Ponsel Anda akan menampilkan peringatan karena file ini bukan dari Play Store, dan itu wajar. <a href=\"#safe\">Cara memastikan aplikasinya aman</a>",
   "en": "Needs Android 16 or newer. Your phone will show a warning because the file is not from the Play Store, which is normal. <a href=\"#safe\">How to check it is safe</a>"
  },
  "n.what-s-new.2j3iur": {
   "t": "Yang baru",
   "en": "What’s new"
  },
  "wn.lead": {
   "t": "Dua aplikasi yang tadinya tetap kecil kini terbuka dalam layar penuh, dan FloatAway mulai lebih cepat setelah ponsel dinyalakan ulang.",
   "en": "Two apps that stayed small now open full screen, and FloatAway starts sooner after a phone restart."
  },
  "n.smart-banka-now-opens.notf9j": {
   "t": "Smart Banka kini selalu terbuka di layar penuh.",
   "en": "Smart Banka now opens full screen every time."
  },
  "wn.li2": {
   "t": "Google Calendar terbuka dalam layar penuh meski sudah terbuka di latar belakang.",
   "en": "Google Calendar opens full screen even when it was already open in the background."
  },
  "wn.li3": {
   "t": "Setelah ponsel dinyalakan ulang, FloatAway mulai lebih cepat, sehingga aplikasi sidebar Anda terbuka dalam layar penuh lebih awal.",
   "en": "After a phone restart, FloatAway starts sooner, so your sidebar apps open full screen earlier."
  },
  "n.sidebar-apps-the-way-y.jqeai4": {
   "t": "Aplikasi sidebar, persis seperti yang Anda harapkan",
   "en": "Sidebar apps, the way you expected"
  },
