  "n.it-knows-when-you-tap.7qhf9o": {
   "t": "Alam nito kapag nag-tap ka ng app sa Smart Sidebar, pati mga cloned app.",
   "en": "It knows when you tap a Smart Sidebar app, cloned apps too."
  },
  "n.a-tiny-invisible-windo.t5idr7": {
   "t": "Isang maliit at hindi nakikitang window, habang bukas lang ang sidebar.",
   "en": "A tiny invisible window, only while the sidebar is open."
  },
  "n.shared-files-open-full.zjpovm": {
   "t": "Full screen din bumubukas ang mga shared file. Para ibalik ito sa dati, i-off ang FloatAway bago mo ito i-uninstall. Ino-on din nito ang “Disable adb authorization timeout” sa Developer options, kaya isang beses mo lang gagawin ang Wireless debugging step. Mananatiling naka-on iyon hangga't hindi mo ito ina-off doon.",
   "en": "Shared files open full screen too. To undo this, switch FloatAway off before you remove it. It also turns on “Disable adb authorization timeout” in Developer options, so you do the Wireless debugging step once. That one stays on until you turn it off there."
  },
  "n.when-you-add-a-folder.508tdj": {
   "t": "Kapag nagdagdag ka ng folder, ito na ang magta-tap ng Edit para sa iyo. Nakikita nito kung nasaan ang mga button, pero hindi kailanman ang anumang salita.",
   "en": "When you add a folder, it taps Edit for you. It sees where buttons are, never any words."
  },
  "n.there-is-no-account-to.9f0z13": {
   "t": "Walang account na kailangang i-sign in.",
   "en": "There is no account to sign in to."
  },
  "n.it-cannot-read-your-me.7t1drp": {
   "t": "Hindi nito nababasa ang mga message o file mo, o anumang salita sa screen.",
   "en": "It cannot read your messages, your files or any words on screen."
  },
  "n.frequently-asked-quest.kxi6h4": {
   "t": "Mga madalas itanong tungkol sa FloatAway",
   "en": "Frequently asked questions about FloatAway"
  },
  "n.try-it-free-on-your-ow.1gacaq5": {
   "t": "Subukan nang libre sa sarili mong phone nang 14 na araw. Kung hindi bagay sa iyo, i-delete mo lang. Wala kang babayaran.",
   "en": "Try it free on your own phone for 14 days. If it does not suit you, delete it. You owe nothing."
  },
